@import "tailwindcss";

/* Graphite preset (ui-craft) with teal accent rotation.
   Primitive layer only — components consume the semantic utilities below. */
@theme {
  --color-*: initial;

  /* neutrals — cool, hue 255 */
  --color-gray-0: oklch(99% 0.002 255); /* page */
  --color-gray-1: oklch(97% 0.003 255); /* raised surface, panel tint */
  --color-gray-2: oklch(93% 0.004 255); /* hairlines, dividers */
  --color-gray-3: oklch(86% 0.005 255); /* disabled fills */
  --color-gray-6: oklch(55% 0.012 255); /* secondary text */
  --color-gray-7: oklch(42% 0.014 255); /* tertiary headings */
  --color-gray-9: oklch(18% 0.012 255); /* primary text */
  --color-white: oklch(100% 0 0);

  /* accent — deep teal */
  --color-accent: oklch(48% 0.12 195);
  --color-accent-hover: oklch(43% 0.12 195);
  --color-accent-tint: oklch(48% 0.12 195 / 0.08);
  --color-on-accent: oklch(99% 0.002 255);

  /* semantic */
  --color-danger: oklch(52% 0.18 25);

  /* shape — radii vary by element class */
  --radius-input: 0.375rem;
  --radius-card: 0.625rem;

  --shadow-card:
    0 0 0 1px oklch(0% 0 0 / 0.04),
    0 1px 2px oklch(0% 0 0 / 0.05);

  --font-sans:
    ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;

  --ease-out-quart: cubic-bezier(0.16, 1, 0.3, 1);
}

html {
  color-scheme: light;
}

body {
  @apply bg-gray-0 text-gray-9 antialiased;
  font-size: 14px;
  line-height: 1.5;
}

